type ListLatestFindingsRow struct {
	ID              int64
	ScanID          int64
	AssetID         int64
	Type            string
	Fingerprint     string
	Occurrences     int64
	Severity        string
	LicencePolicy   interface{}
	Title           string
	RuleID          sql.NullString
	PackageName     sql.NullString
	PackageVersion  sql.NullString
	FixedVersion    sql.NullString
	Ecosystem       sql.NullString
	Location        sql.NullString
	CVSS            sql.NullFloat64
	EPSS            sql.NullFloat64
	Description     sql.NullString
	ReferencesJSON  string
	Scanner         string
	Scanners        string
	Reachability    sql.NullString
	FirstSeenScanID sql.NullInt64
	Status          string
	State           sql.NullString
	Reason          sql.NullString
	DecidedBy       sql.NullString
	ExpiresAt       sql.NullString
	Expired         int64
	CreatedAt       string
	SortKey         int64
	SortOrder       int64
}

// Findings of the most recent succeeded scan of every non-archived asset, so
// the UI shows the current state of the fleet. Failed, canceled and running
// scans are skipped: when the newest scan failed, its asset still reports the
// previous succeeded scan. Filters and the effective status match
// ListFindingsByScan.
func (q *Queries) ListLatestFindings(ctx context.Context, arg ListLatestFindingsParams) ([]ListLatestFindingsRow, error) {
	rows, err := q.db.QueryContext(ctx, listLatestFindings,
		arg.Now,
		arg.Sort,
		arg.Order,
		arg.AssetID,
		arg.Fingerprint,
		arg.Type,
		arg.Severity,
		arg.Status,
		arg.DecidedBy,
		arg.Fix,
		arg.Dependency,
		arg.HideMaintenance,
		arg.HideTests,
		arg.Query,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListLatestFindingsRow
	for rows.Next() {
		var i ListLatestFindingsRow
		if err := rows.Scan(
			&i.ID,
			&i.ScanID,
			&i.AssetID,
			&i.Type,
			&i.Fingerprint,
			&i.Occurrences,
			&i.Severity,
			&i.LicencePolicy,
			&i.Title,
			&i.RuleID,
			&i.PackageName,
			&i.PackageVersion,
			&i.FixedVersion,
			&i.Ecosystem,
			&i.Location,
			&i.CVSS,
			&i.EPSS,
			&i.Description,
			&i.ReferencesJSON,
			&i.Scanner,
			&i.Scanners,
			&i.Reachability,
			&i.FirstSeenScanID,
			&i.Status,
			&i.State,
			&i.Reason,
			&i.DecidedBy,
			&i.ExpiresAt,
			&i.Expired,
			&i.CreatedAt,
			&i.SortKey,
			&i.SortOrder,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
